namespace SimpleBanking;
internal sealed record AttentionItem(string Key,int Priority,string Title,string Body,string Detail,Entry? Entry);
internal static class AttentionInbox
{
    internal static List<AttentionItem> Analyze(IEnumerable<Entry> input,DateOnly today,AccountFinanceSettings settings){
        var history=input.Where(e=>!e.Pending&&e.Date<=today&&e.Date>=today.AddDays(-90)).OrderByDescending(e=>e.Date).ToArray();var expenses=history.Where(e=>e.Amount<0).ToArray();var recent14=expenses.Where(e=>e.Date>=today.AddDays(-14)).ToArray();var recent7=expenses.Where(e=>e.Date>=today.AddDays(-7)).ToArray();var result=new List<AttentionItem>();
        string Name(Entry e)=>RecurringCosts.Merchant(e);string Money(Entry e)=>UiFormat.Money(Math.Abs(e.Amount),e.Currency);
        DateOnly Expected(DateOnly anchor)=>new(anchor.Year,anchor.Month,Math.Min(settings.EffectiveSalaryDay,DateTime.DaysInMonth(anchor.Year,anchor.Month)));
        var expected=Expected(today);if(expected>today)expected=Expected(today.AddMonths(-1));
        if(history.Length>0&&today>expected.AddDays(settings.SalaryTolerance+2)&&!history.Any(e=>e.Amount>0&&RecurringCosts.SalaryCredit(e)&&e.Date>=expected.AddDays(-settings.SalaryTolerance)))result.Add(new("salary-missing",1,"Gehaltseingang noch nicht erkannt","Kein Gehaltseingang gefunden — erwartet um den "+expected.ToString("dd.MM.")+".","Heute ist der "+today.Day+".",null));
        foreach(var group in recent7.GroupBy(e=>(Name(e),e.Amount)).Where(g=>g.Count()>1)){
            var tx=group.First();if(RecurringCosts.Category(group.Key.Item1)!="other"&&-tx.Amount<30)continue;
            result.Add(new("duplicate:"+group.Key,1,"Möglicherweise doppelt: "+Name(tx),"Zwei Abbuchungen mit gleichem Betrag innerhalb von 7 Tagen.",Money(tx)+" × "+group.Count(),tx));
        }
        foreach(var p in RecurringCosts.Analyze(expenses)){var tx=recent14.FirstOrDefault(e=>Name(e)==p.Merchant);if(tx==null)continue;decimal difference=-tx.Amount-p.AverageAmount;if(difference>Math.Max(1,p.AverageAmount*.05m))result.Add(new("sub-increase:"+p.Merchant,2,p.Merchant+" kostet mehr als üblich","Die Abbuchung liegt über deinem üblichen Betrag.",UiFormat.Money(p.AverageAmount,tx.Currency)+" → "+Money(tx),tx));}
        var unusual=new List<AttentionItem>();foreach(var group in expenses.GroupBy(Name).Where(g=>g.Count()>=3)){var amounts=group.Select(e=>-e.Amount).Order().ToArray();decimal median=amounts.Length%2==0?(amounts[amounts.Length/2-1]+amounts[amounts.Length/2])/2:amounts[amounts.Length/2];if(median<=5)continue;foreach(var tx in recent7.Where(e=>Name(e)==group.Key&&-e.Amount>median*2&&-e.Amount-median>20))unusual.Add(new("unusual-expense:"+group.Key,2,"Ungewöhnlich hohe Ausgabe bei "+group.Key,"Diese Abbuchung ist deutlich höher als dein üblicher Betrag dort.",Money(tx)+" (normal ~"+UiFormat.Money(median,tx.Currency)+")",tx));}result.AddRange(unusual.Take(2));
        var knownIbans=expenses.Where(e=>e.Date<today.AddDays(-14)).Select(e=>e.CounterpartyIban).ToHashSet();result.AddRange(recent14.Where(e=>e.CounterpartyIban.Length>0&&!knownIbans.Contains(e.CounterpartyIban)&&(e.PurposeCode=="DBIT"||(e.AdditionalInformation+" "+e.Purpose).Contains("LASTSCHRIFT",StringComparison.OrdinalIgnoreCase)||e.AdditionalInformation.Contains("SEPA",StringComparison.OrdinalIgnoreCase))).Take(2).Select(e=>new AttentionItem("new-debit:"+e.CounterpartyIban,2,"Neue Lastschrift: "+Name(e),"Diese IBAN hat bisher noch keine Lastschrift eingezogen.",Money(e)+" · "+e.Date.ToString("dd.MM.yyyy"),e)));
        var known=history.Where(e=>e.Date<today.AddDays(-14)).Select(Name).ToHashSet();result.AddRange(recent14.Where(e=>!known.Contains(Name(e))&&Name(e) is not ("" or "Unbekannt" or "Bargeldabhebung")).DistinctBy(Name).Take(2).Select(e=>new AttentionItem("new-merchant:"+Name(e),3,"Erster Einkauf bei "+Name(e),"Dieser Händler ist in deiner bisherigen Transaktionshistorie neu.",Money(e),e)));
        var monthStart=new DateOnly(today.Year,today.Month,1);var spikes=new List<(AttentionItem Item,decimal Ratio)>();foreach(var category in expenses.Where(e=>e.Date>=monthStart).GroupBy(e=>e.Category)){decimal current=-category.Sum(e=>e.Amount);var months=expenses.Where(e=>e.Date<monthStart&&e.Category==category.Key).GroupBy(e=>(e.Date.Year,e.Date.Month)).Select(g=>-g.Sum(e=>e.Amount)).ToArray();if(months.Length<2)continue;decimal average=months.Average();if(average>20&&current>average*1.6m)spikes.Add((new("cat-spike:"+category.Key,3,category.Key+" diesen Monat deutlich höher",$"Etwa {current/average:N1}× mehr als üblich.",UiFormat.Money(average,category.First().Currency)+" / Monat",null),current/average));}result.AddRange(spikes.OrderByDescending(s=>s.Ratio).Take(1).Select(s=>s.Item));
        result.AddRange(input.Where(e=>e.ReminderAt is {} at&&DateOnly.FromDateTime(at)<=today&&!e.ReminderDone).Select(e=>new AttentionItem("reminder:"+e.Id,3,"Erinnerung: "+e.Merchant,e.Note.Length>0?e.Note:e.Purpose,e.ReminderAt!.Value.ToString("g"),e)));
        return result.OrderBy(c=>c.Priority).DistinctBy(c=>c.Key).ToList();
    }
}
internal sealed partial class MainWindow
{
    internal int AttentionCount(){if(IsLocked)return 0;var today=DateOnly.FromDateTime(DateTime.Today);var snapshot=AnalysisSnapshot();return snapshot.Accounts.Sum(a=>AttentionInbox.Analyze(snapshot.Entries.Where(e=>e.AccountId==a.Id),today,Preferences.FinanceFor(a.Id)).Count(c=>!data.AttentionReadUntil.TryGetValue(a.Id+"/"+c.Key,out var until)||until<today));}
    internal void OpenAttentionInbox(){
        if(!RequireUnlocked())return;var snapshot=AnalysisSnapshot();var today=DateOnly.FromDateTime(DateTime.Today);
        var cards=snapshot.Accounts.SelectMany(a=>AttentionInbox.Analyze(snapshot.Entries.Where(e=>e.AccountId==a.Id),today,Preferences.FinanceFor(a.Id)).Select(c=>c with{Key=a.Id+"/"+c.Key})).Where(c=>!data.AttentionReadUntil.TryGetValue(c.Key,out var until)||until<today).OrderBy(c=>c.Priority).Take(5).ToArray();
        using var dialog=new Form{Text="Attention Inbox",ClientSize=new Size(440,520),StartPosition=FormStartPosition.CenterParent,BackColor=BackColor,Font=Font};var list=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16,14,16,14)};dialog.Controls.Add(list);
        if(cards.Length==0){list.Controls.Add(DashboardWindow.Label("Heute nichts Auffälliges",20,true));list.Controls.Add(DashboardWindow.Label("Alle Umsätze sehen normal aus."));}
        foreach(var item in cards){var card=new RoundedCard{Width=390,MinimumSize=new Size(390,0)};card.Controls.Add(DashboardWindow.Label(item.Title,14,true));card.Controls.Add(DashboardWindow.Label(item.Body,12));card.Controls.Add(DashboardWindow.Label(item.Detail,11));foreach(var label in card.Controls.OfType<Label>())label.MaximumSize=new Size(350,0);if(item.Entry is {} entry)card.Controls.Add(DashboardWindow.ActionButton("Ansehen",()=>OpenEntryDetail(entry)));list.Controls.Add(card);}
        var read=DashboardWindow.ActionButton("Gelesen",()=>{foreach(var c in cards)data.AttentionReadUntil[c.Key]=today.AddDays(7);Save();RefreshEntries();dialog.Close();});var header=new FlowLayoutPanel{Dock=DockStyle.Top,Height=58,Padding=new Padding(18,12,0,0)};header.Controls.Add(DashboardWindow.Label("Attention Inbox",18,true));header.Controls.Add(read);dialog.Controls.Add(header);dialog.ShowDialog(this);
    }
}
